/**
 * Equirectangular → LDR cube texture — CODE-SPLIT.
 *
 * Babylon's `EquiRectangularCubeTexture` builds a FLOAT cube, which is
 * unusable on devices without float LINEAR FILTERING (measured on a real
 * WebGPU/D3D12 machine: `textureFloatLinearFiltering === false`). There,
 * Babylon strips the mips and the PBR reflection path then samples mip 1 on a
 * 1-mip texture — a validation error every frame.
 *
 * A sky image is LDR to begin with (PNG/JPEG), so a float cube buys nothing.
 * This samples the equirect into six UNSIGNED-BYTE faces and builds a
 * RawCubeTexture, which filters and mip-maps on every engine. Measured on the
 * same machine that fails the float path: installs, ready, zero GL errors.
 *
 * A 2D texture with EQUIRECTANGULAR_MODE is NOT an alternative: WebGPU
 * rejects a 2D view where a cube is bound ("Dimension (TextureViewDimension::
 * e2D)"), so the cube conversion is the portable path.
 */
import { RawCubeTexture } from '@babylonjs/core/Materials/Textures/rawCubeTexture';
import { CubeMapToSphericalPolynomialTools } from '@babylonjs/core/Misc/HighDynamicRange/cubemapToSphericalPolynomial';
import type { BaseTexture } from '@babylonjs/core/Materials/Textures/baseTexture';
import type { Scene } from '@babylonjs/core/scene';
import { isHeld, worldAccessOf } from '../../net/worldRequests';

/**
 * Longitude offset (radians) aligning our cube orientation with Blender's
 * equirect mapping — determined EMPIRICALLY by A/B against the corpus's Eevee
 * render (the pane must reflect the same band of the image, or the room
 * mirrors sky where Blender mirrors trees).
 */
const LON_OFFSET = 0;

/** Cube face resolution. 256 is ample for an ambient/reflection term. */
export const CUBE_FACE_SIZE = 256;

/** Face direction basis: +X, -X, +Y, -Y, +Z, -Z (Babylon cube face order). */
const FACE_DIRS: ReadonlyArray<(u: number, v: number) => [number, number, number]> = [
  (u, v) => [1, -v, -u],
  (u, v) => [-1, -v, u],
  (u, v) => [u, 1, v],
  (u, v) => [u, -1, -v],
  (u, v) => [u, -v, 1],
  (u, v) => [-u, -v, -1],
];

/**
 * The image at `url`, decoded. An image element would have the browser ask
 * for the address with the page's cookies, so the bytes are fetched as the
 * scene's world may fetch them and decoded from there. An address the page
 * already holds (`data:`) involves no request and loads as an element.
 */
async function loadImage(url: string, scene: Scene): Promise<HTMLImageElement | ImageBitmap> {
  if (!isHeld(url)) {
    const response = await worldAccessOf(scene).fetch(url);
    if (!response.ok) throw new Error(`could not load environment image: ${url}`);
    return createImageBitmap(await response.blob());
  }
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`could not load environment image: ${url}`));
    img.src = url;
  });
}

/**
 * Build an LDR cube texture from an equirectangular image. Returns null when
 * the image cannot be read (a 2D context is unavailable, or the fetch fails) —
 * the caller then keeps its existing environment rather than failing the load.
 */
/**
 * The built environment cube PLUS the source image's hemisphere means —
 * returned so the SHELL's irradiance emulation is derived from the WORLD's
 * own image at load time, never from constants (constants would bake one
 * particular sky into every world). Means are display-space byte averages
 * (0..1, not linearized) — the measure the fill's look is calibrated against.
 */
export interface EquirectCubeResult {
  cube: BaseTexture;
  /** Mean [r,g,b] of the equirect's upper half (the sky hemisphere). */
  skyAverage: readonly [number, number, number];
  /** Mean [r,g,b] of the equirect's lower half (the ground hemisphere). */
  groundAverage: readonly [number, number, number];
}

export async function createEquirectCubeTexture(
  url: string,
  scene: Scene,
  size: number = CUBE_FACE_SIZE,
): Promise<EquirectCubeResult | null> {
  let source: ImageData;
  try {
    const img = await loadImage(url, scene);
    const canvas = document.createElement('canvas');
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext('2d');
    if (ctx === null) return null;
    ctx.drawImage(img, 0, 0);
    source = ctx.getImageData(0, 0, img.width, img.height);
  } catch {
    return null;
  }

  const { width, height, data } = source;
  const faces: ArrayBufferView[] = [];
  for (const dir of FACE_DIRS) {
    const face = new Uint8Array(size * size * 4);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const u = (2 * (x + 0.5)) / size - 1;
        const v = (2 * (y + 0.5)) / size - 1;
        const d = dir(u, v);
        const len = Math.hypot(d[0], d[1], d[2]);
        const nx = d[0] / len;
        const ny = d[1] / len;
        const nz = d[2] / len;
        // Equirect lookup: longitude from atan2, latitude from asin.
        const sx = Math.min(
          width - 1,
          Math.max(0, Math.floor((((Math.atan2(nz, nx) + LON_OFFSET) / (2 * Math.PI) + 0.5) % 1 + 1) % 1 * width)),
        );
        const sy = Math.min(
          height - 1,
          Math.max(0, Math.floor((0.5 - Math.asin(ny) / Math.PI) * height)),
        );
        const si = (sy * width + sx) * 4;
        const di = (y * size + x) * 4;
        face[di] = data[si]!;
        face[di + 1] = data[si + 1]!;
        face[di + 2] = data[si + 2]!;
        face[di + 3] = 255;
      }
    }
    faces.push(face);
  }

  // format RGBA(5), type UNSIGNED_INT/byte(0), generateMipMaps, no invertY,
  // TRILINEAR sampling(3) — all numeric to avoid pulling constants modules.
  const cube = new RawCubeTexture(scene, faces, size, 5, 0, true, false, 3);

  // SPHERICAL HARMONICS — attached, with its measured behavior on record
  // (three A/B measurements on the reference WebGPU device):
  //  1. scaling the coefficients 20x changed ZERO pixels — the shader does
  //     not read them proportionally here;
  //  2. REMOVING the polynomial dimmed the whole frame ~10% (panes -13%) —
  //     presence toggles a shader path with a real, broadly-distributed
  //     light contribution;
  //  3. the world's DIFFUSE look is therefore carried by the caller's
  //     hemispheric fill (declared `diffuse`, tinted from the hemisphere
  //     means below), with SH kept as part of the calibrated cube build.
  // Cross-device determinism of (2) is exactly what the fidelity harness
  // (tooling/fidelity) exists to check on other hardware.
  try {
    const toFloat = (face: ArrayBufferView): Float32Array => {
      const bytes = face as Uint8Array;
      const out = new Float32Array(bytes.length);
      for (let i = 0; i < bytes.length; i++) out[i] = bytes[i]! / 255;
      return out;
    };
    cube.sphericalPolynomial = CubeMapToSphericalPolynomialTools.ConvertCubeMapToSphericalPolynomial({
      right: toFloat(faces[0]!), left: toFloat(faces[1]!), up: toFloat(faces[2]!),
      down: toFloat(faces[3]!), front: toFloat(faces[4]!), back: toFloat(faces[5]!),
      size, format: 5, type: 1, gammaSpace: true,
    });
  } catch { /* probe only */ }

  // Hemisphere means from the SOURCE equirect (upper half = sky, lower half
  // = ground) — the data the caller's irradiance fill is tinted with.
  const half = (y0: number, y1: number): [number, number, number] => {
    let r = 0;
    let g = 0;
    let b = 0;
    let n = 0;
    for (let y = y0; y < y1; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;
        r += data[i]!;
        g += data[i + 1]!;
        b += data[i + 2]!;
        n++;
      }
    }
    return [r / n / 255, g / n / 255, b / n / 255];
  };
  const skyAverage = half(0, Math.floor(height / 2));
  const groundAverage = half(Math.floor(height / 2), height);

  // ROUGHNESS→MIP MAPPING, set directly instead of HDRFiltering (measured):
  // the raw cube DOES have auto-generated mips, but without lodGenerationScale
  // the PBR pipeline samples mip 0 for every roughness — rough walls speckled
  // with sharp texture. HDRFiltering fixed that as a side effect but WASHED
  // THE COLOR OUT: its rewrite desaturated the vivid source to gray (verified
  // by running the identical face conversion CPU-side — faces fully colored —
  // while the rendered reflection was monochrome). Box-filtered mips plus the
  // standard env lod mapping give blurred rough reflections AND keep chroma.
  const lodCube = cube as unknown as { lodGenerationScale: number; lodGenerationOffset: number };
  lodCube.lodGenerationScale = 0.8;
  lodCube.lodGenerationOffset = 0;

  return { cube, skyAverage, groundAverage };
}

/** The module shape applyEnvironment consumes (injectable for unit tests). */
export type EquirectCubeModule = {
  createEquirectCubeTexture: typeof createEquirectCubeTexture;
};
